import{_ as m,a0 as s,w as p,s as d,I as a,x as t,a1 as o,A as r,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"提升 emacs 生產力的十大最佳插件 | LCTT x X-CMD","titleTemplate":false,"description":"提升 emacs 生產力的十大最佳插件 | LCTT (201601) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"提升 emacs 生產力的十大最佳插件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"提升 emacs 生產力的十大最佳插件 | LCTT (201601) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201601/20151225 What are the best plugins to increase productivity on Emacs","title":"提升 emacs 生產力的十大最佳插件","tag":"201601","desc":""},"relativePath":"201601/20151225 What are the best plugins to increase productivity on Emacs.md","filePath":"[post].md"}'),n={name:"201601/20151225 What are the best plugins to increase productivity on Emacs.md"};function c(f,e,u,h,g,_){const i=s("Link");return p(),d("div",null,[e[22]||(e[22]=a("h1",{id:"提升-emacs-生產力的十大最佳插件",tabindex:"-1"},[t("提升 emacs 生產力的十大最佳插件 "),a("a",{class:"header-anchor",href:"#提升-emacs-生產力的十大最佳插件","aria-label":"Permalink to “提升 emacs 生產力的十大最佳插件”"},"​")],-1)),a("p",null,[e[1]||(e[1]=t("一年前的這個時候，我想要尋找",-1)),o(i,{href:"http://xmodulo.com/turn-vim-full-fledged-ide.html"},{default:r(()=>[...e[0]||(e[0]=[t("將 Vim 打造成一個成熟的全功能的 IDE",-1)])]),_:1}),e[2]||(e[2]=t(" 的最好插件。有趣的是，那篇文章的很多評論提到了 Emacs 已經大部分有了這些內置插件，已經是一個很棒的 IDE 了。儘管我對 Emacs 的難以置信的多樣化表示贊同，它依舊不是一個可以開箱即用的高級編輯器。還好，其龐大的插件庫可以解決這個問題。但在過多的選擇中，有時很難弄清該如何入手。因此，現在讓我試着收集一個不可或缺的插件的簡短列表，來提升你使用 Emacs 時的工作效率。 雖然我主要側重於與編程相關的生產力提升，但是這些插件對所有人或不同用途都是有用的。",-1))]),e[23]||(e[23]=l('<h3 id="_1-ido-mode" tabindex="-1">1. Ido-mode <a class="header-anchor" href="#_1-ido-mode" aria-label="Permalink to “1. Ido-mode”">​</a></h3><p><img src="https://c2.staticflickr.com/6/5718/23311895573_c1fb34337c_c.jpg" alt=""></p><p>Ido 或許是對新手最有用的一個插件，Ido 的意思是交互式工作（interactively do）。它取代了大部分的用花哨字符匹配菜單的枯燥提示。好比説，它用列出了當前目錄所有文件的列表來取代了常規的打開文件提示符。輸入一些字符，Ido 將嘗試匹配最合適的文件。它通過可視化讓你的操作變得更容易，這也是一個快速遍歷所有文件都有相同前綴的文件夾的方法。</p><h3 id="_2-smex" tabindex="-1">2. Smex <a class="header-anchor" href="#_2-smex" aria-label="Permalink to “2. Smex”">​</a></h3><p><img src="https://c2.staticflickr.com/2/1517/23310442314_2a22a60c34_c.jpg" alt=""></p><p>它不算最著名的一個、但卻是一個替代 Ido-mode 的好選擇：Smex 可以優雅的替代普通的<code>M-x</code>提示符，靈感大部分來自於 Ido-mode。它也給調用<code>M-x</code>後輸入的命令帶來了同樣的交互搜索能力。它簡單而有效，是一個為常用操作提升效率的最好方法。</p><h3 id="_3-auto-complete" tabindex="-1">3. Auto Complete <a class="header-anchor" href="#_3-auto-complete" aria-label="Permalink to “3. Auto Complete”">​</a></h3><p><img src="https://c2.staticflickr.com/6/5794/23643004900_3042f77952_c.jpg" alt=""></p><p>知道這個插件的存在之前，我在 Emacs 裏面有一半的時間花在敲擊 <code>M-/</code> 來補完單詞上。現在，我有一個漂亮的彈出菜單可以為我做自動補全。無須多説，我們都需要它。</p><h3 id="_4-yasnippet" tabindex="-1">4. YASnippet <a class="header-anchor" href="#_4-yasnippet" aria-label="Permalink to “4. YASnippet”">​</a></h3><p><img src="https://c2.staticflickr.com/2/1688/23830403072_0d8df6ef4c_b.jpg" alt=""></p><p>這是真正的程序員必備利器。總有一些代碼片段會讓我們覺得我們一輩子都在寫它。對我來説，就是調試 PHP 時不斷輸入的 <code>var_dump(...);exit;</code>。經過一段時間一遍又一遍的輸入<code>var_dump(...);exit;</code>，我覺得我可以預先把其做成錄製好的、方便用到的代碼片段。使用 YASnippets，可以很容易導入代碼片段文件或者自己做個。之後，只要按下一個 tab 鍵，就可以將一個小的關鍵詞擴展成一大段預先寫好的代碼，然後可以很方便地在裏面修改。</p><h3 id="_5-org-mode" tabindex="-1">5. Org-mode <a class="header-anchor" href="#_5-org-mode" aria-label="Permalink to “5. Org-mode”">​</a></h3><p><img src="https://c2.staticflickr.com/6/5687/23570808789_d683c949e4.jpg" alt=""></p>',14)),a("p",null,[e[4]||(e[4]=t("免責聲明，我最近才開始使用 Org-mode，但它已經深深的吸引了我。從我看過數以百計的文章來説，Org-mode 可以改變你的生活。它背後的想法很簡單：它是一種用普通文本做簡單備註的模式，可以很容易地在任務列表和各種數據中轉來轉去，並進行一些比如按優先級或到期日期的過濾，或設置一個重複日期。然而，雖然思路簡單，但你可以做到很多，用各種方法用於各種用途。與其去看一個長長的介紹，我覺得你可以去讀讀",-1)),o(i,{href:"http://orgmode.org/worg/org-tutorials/"},{default:r(()=>[...e[3]||(e[3]=[t("現有教程",-1)])]),_:1}),e[5]||(e[5]=t("，有很多視頻可以看，自己去體驗一下 Org-mode 是多麼強大。",-1))]),e[24]||(e[24]=a("h3",{id:"_6-helm",tabindex:"-1"},[t("6. Helm "),a("a",{class:"header-anchor",href:"#_6-helm","aria-label":"Permalink to “6. Helm”"},"​")],-1)),e[25]||(e[25]=a("p",null,[a("img",{src:"https://c2.staticflickr.com/2/1489/23310442334_5e6db22b79_c.jpg",alt:""})],-1)),a("p",null,[e[7]||(e[7]=t("一些使用者喜歡它，但是其他人沒有這麼大的使用熱情。我是後者的一部分。但在擁有這樣一個龐大的追隨者的情況下，是不能不提到它的。Helm 旨在完全變換你的 Emacs 使用體驗。簡單來説，Helm 是一個在 Emacs 中幫助你快速找到一個文件或命令的框架。根據你的輸入，它將嘗試使用詞語自動完成來引導你將大腦的念頭變為行動。起初感覺有點奇怪，但對一些人來説，Helm 本身就是一個信仰。雖然我不是 Helm 的粉絲，我欣賞 helm-occur 這一個偉大的工具可以在一個大文檔搜索字符串並且在一個單獨的緩衝區顯示所有匹配結果，以便很容易在它們之間跳轉。如果你正在尋找一個快速演示來了解 Helm 能做什麼，我推薦",-1)),o(i,{href:"http://tuhdo.github.io/helm-intro.html"},{default:r(()=>[...e[6]||(e[6]=[t("這篇文章",-1)])]),_:1}),e[8]||(e[8]=t("。",-1))]),e[26]||(e[26]=l('<h3 id="_7-ace-jump-mode" tabindex="-1">7. ace-jump-mode <a class="header-anchor" href="#_7-ace-jump-mode" aria-label="Permalink to “7. ace-jump-mode”">​</a></h3><p><img src="https://c2.staticflickr.com/2/1710/23856168871_6df1faa565_c.jpg" alt=""></p><p>這是另一個有一大羣追隨者的插件，我正在試圖成為 ace-jump-mode 的粉絲。掌握這個插件，你會體驗到超越鼠標感受。簡單描述一下，通過你選擇的快捷方式觸發 ace-jump-mode 後，你會被提示輸入字符。輸入一個字符，所有以該字符開頭的單詞中的那個字符就會替換成一個唯一字符並被高亮。輸入一個屏幕上的高亮字符，你的光標會直接跳轉到高亮顯示的那個詞。我不得不承認，這讓我使用它時有點反應不過來，但是，一旦你掌握它，它將顯著提升你在一個文檔裏的移動速度。（LCTT 譯註：用文字描述比較困難，如截圖中，你輸入的是一個“i”，然後屏幕中所有以“i”開頭的單詞中的那個“i”都被替換成了從 a 到 z 的字符，並高亮；你可以輸入這些高亮的字符直接跳轉到那個位置。）</p><h3 id="_8-find-file-in-project" tabindex="-1">8. find-file-in-project <a class="header-anchor" href="#_8-find-file-in-project" aria-label="Permalink to “8. find-file-in-project”">​</a></h3><p><img src="https://c2.staticflickr.com/2/1492/23570808809_96ec8454a9_c.jpg" alt=""></p><p>如果你喜歡 Sublime text 以及它可以用非常方便的<code>Ctrl-p</code>模糊搜索來打開一個項目中的任何文件的功能，你將會喜歡上 find-file-in-project （簡稱 ffip）的。使用設置指定了您的版本控制的根文件夾後，您可以輕鬆地調出一個很酷的文本條，通過快速掃描和搜索你的代碼，來根據你輸入的名稱找到匹配的文件。我喜歡把它綁定到鍵盤上的 F6 鍵。如果你不知道整個目錄從上到下的複雜結構，這很簡單，而且非常易用。</p><h3 id="_9-flymake" tabindex="-1">9. Flymake <a class="header-anchor" href="#_9-flymake" aria-label="Permalink to “9. Flymake”">​</a></h3><p><img src="https://c2.staticflickr.com/6/5708/23310442354_cbba657ed3.jpg" alt=""></p><p>對 IDE 的愛好者來説，我認為語法檢查器是 IDE 最強大的特性之一，它非常適合初學者和方便了那些疲憊的程序員。感謝 Flymake，Emacs 用户也可以享受到了語法檢查器。因為我工作中用 PHP 很多，Flymake 就不需要任何額外的配置。當我寫代碼的時候，它會自動檢查我的代碼和高亮任何一個包含問題的行。對於編譯語言，Flymake 將尋找一個用於檢查你的代碼的 Makefile。真神奇。</p><h3 id="_10-electric-pair" tabindex="-1">10. electric-pair <a class="header-anchor" href="#_10-electric-pair" aria-label="Permalink to “10. electric-pair”">​</a></h3><p>最後，但並非最不重要，在我看來，electric-pair 是最簡單但最強大的插件之一。它會自動關閉你輸入的括號。它起初看起來並不是很有用，但相信我，在被尋找配對括號折磨幾百次之後，你會很高興有這麼一個插件，可以確保你所有的表達式的括號都是一一對應的。</p><p>總結一下，Emacs 是一個奇妙的工具。這可不是一個令人驚訝的説法。試試這些插件，看着你的效率直線飆升吧。這個列表當然不是詳盡的列表。如果你想貢獻你的建議，請在評論中這樣做。我自己一直在尋找新的插件來試着發現 Emacs 的新體驗。</p><hr>',13)),a("p",null,[e[10]||(e[10]=t("via: ",-1)),o(i,{href:"http://xmodulo.com/best-plugins-to-increase-productivity-on-emacs.html"},{default:r(()=>[...e[9]||(e[9]=[t("http://xmodulo.com/best-plugins-to-increase-productivity-on-emacs.html",-1)])]),_:1})]),a("p",null,[e[14]||(e[14]=t("作者：",-1)),o(i,{href:"http://xmodulo.com/author/adrien"},{default:r(()=>[...e[11]||(e[11]=[t("Adrien Brochard",-1)])]),_:1}),e[15]||(e[15]=t(" 譯者：",-1)),o(i,{href:"https://github.com/zky001"},{default:r(()=>[...e[12]||(e[12]=[t("zky001",-1)])]),_:1}),e[16]||(e[16]=t(" 校對：",-1)),o(i,{href:"https://github.com/wxy"},{default:r(()=>[...e[13]||(e[13]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[19]||(e[19]=t("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[17]||(e[17]=[t("LCTT",-1)])]),_:1}),e[20]||(e[20]=t(" 原創編譯，",-1)),o(i,{href:"https://linux.cn/"},{default:r(()=>[...e[18]||(e[18]=[t("Linux中國",-1)])]),_:1}),e[21]||(e[21]=t(" 榮譽推出",-1))])])}const T=m(n,[["render",c]]);export{k as __pageData,T as default};
